import type { NistCatalogFamily } from "../types.js";

// Generated from NIST OSCAL content. Do not edit by hand.
export const FAMILY_AT: NistCatalogFamily = {"code":"AT","name":"Awareness and Training","controls":[{"id":"AT-1","oscal_id":"at-1","family":"AT","title":"Policy and Procedures","statement":"a. Develop, document, and disseminate to <organization-defined personnel or roles>:\n  Develop, document, and disseminate to <organization-defined personnel or roles>:\n  1. <organization-defined parameter> awareness and training policy that:\n    <organization-defined parameter> awareness and training policy that:\n    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and\n    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and\n  2. Procedures to facilitate the implementation of the awareness and training policy and the associated awareness and training controls;\nb. Designate an <official> to manage the development, documentation, and dissemination of the awareness and training policy and procedures; and\nc. Review and update the current awareness and training:\n  Review and update the current awareness and training:\n  1. Policy <frequency> and following <events> ; and\n  2. Procedures <frequency> and following <events>.","supplemental_guidance":"Awareness and training policy and procedures address the controls in the AT family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of awareness and training policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to awareness and training policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure.","implementation_level":"organization","parameters":[{"id":"at-1_prm_1","label":"organization-defined personnel or roles"},{"id":"at-01_odp.01","label":"personnel or roles"},{"id":"at-01_odp.02","label":"personnel or roles"},{"id":"at-01_odp.03","label":"","choices":["organization-level","mission/business process-level","system-level"],"how_many":"one-or-more"},{"id":"at-01_odp.04","label":"official"},{"id":"at-01_odp.05","label":"frequency"},{"id":"at-01_odp.06","label":"events"},{"id":"at-01_odp.07","label":"frequency"},{"id":"at-01_odp.08","label":"events"}],"objectives":[{"id":"at-1_obj.a-1","label":"AT-01a.[01]","text":"an awareness and training policy is developed and documented;"},{"id":"at-1_obj.a-2","label":"AT-01a.[02]","text":"the awareness and training policy is disseminated to {{ insert: param, at-01_odp.01 }};"},{"id":"at-1_obj.a-3","label":"AT-01a.[03]","text":"awareness and training procedures to facilitate the implementation of the awareness and training policy and associated access controls are developed and documented;"},{"id":"at-1_obj.a-4","label":"AT-01a.[04]","text":"the awareness and training procedures are disseminated to {{ insert: param, at-01_odp.02 }}."},{"id":"at-1_obj.a.1.a-1","label":"AT-01a.01(a)[01]","text":"the {{ insert: param, at-01_odp.03 }} awareness and training policy addresses purpose;"},{"id":"at-1_obj.a.1.a-2","label":"AT-01a.01(a)[02]","text":"the {{ insert: param, at-01_odp.03 }} awareness and training policy addresses scope;"},{"id":"at-1_obj.a.1.a-3","label":"AT-01a.01(a)[03]","text":"the {{ insert: param, at-01_odp.03 }} awareness and training policy addresses roles;"},{"id":"at-1_obj.a.1.a-4","label":"AT-01a.01(a)[04]","text":"the {{ insert: param, at-01_odp.03 }} awareness and training policy addresses responsibilities;"},{"id":"at-1_obj.a.1.a-5","label":"AT-01a.01(a)[05]","text":"the {{ insert: param, at-01_odp.03 }} awareness and training policy addresses management commitment;"},{"id":"at-1_obj.a.1.a-6","label":"AT-01a.01(a)[06]","text":"the {{ insert: param, at-01_odp.03 }} awareness and training policy addresses coordination among organizational entities;"},{"id":"at-1_obj.a.1.a-7","label":"AT-01a.01(a)[07]","text":"the {{ insert: param, at-01_odp.03 }} awareness and training policy addresses compliance; and"},{"id":"at-1_obj.a.1.b","label":"AT-01a.01(b)","text":"the {{ insert: param, at-01_odp.03 }} awareness and training policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines; and"},{"id":"at-1_obj.b","label":"AT-01b.","text":"the {{ insert: param, at-01_odp.04 }} is designated to manage the development, documentation, and dissemination of the awareness and training policy and procedures;"},{"id":"at-1_obj.c.1-1","label":"AT-01c.01[01]","text":"the current awareness and training policy is reviewed and updated {{ insert: param, at-01_odp.05 }};"},{"id":"at-1_obj.c.1-2","label":"AT-01c.01[02]","text":"the current awareness and training policy is reviewed and updated following {{ insert: param, at-01_odp.06 }};"},{"id":"at-1_obj.c.2-1","label":"AT-01c.02[01]","text":"the current awareness and training procedures are reviewed and updated {{ insert: param, at-01_odp.07 }};"},{"id":"at-1_obj.c.2-2","label":"AT-01c.02[02]","text":"the current awareness and training procedures are reviewed and updated following {{ insert: param, at-01_odp.08 }}."}],"methods":[{"method":"examine","label":"AT-01-Examine"},{"method":"interview","label":"AT-01-Interview"}],"references":[{"title":"OMB A-130"},{"title":"SP 800-12"},{"title":"SP 800-30"},{"title":"SP 800-39"},{"title":"SP 800-50"},{"title":"SP 800-100"}],"related_controls":["PM-9","PS-8","SI-12"]},{"id":"AT-2","oscal_id":"at-2","family":"AT","title":"Literacy Training and Awareness","statement":"a. Provide security and privacy literacy training to system users (including managers, senior executives, and contractors):\n  Provide security and privacy literacy training to system users (including managers, senior executives, and contractors):\n  1. As part of initial training for new users and <organization-defined frequency> thereafter; and\n  2. When required by system changes or following <organization-defined events>;\nb. Employ the following techniques to increase the security and privacy awareness of system users <awareness techniques>;\nc. Update literacy training and awareness content <frequency> and following <events> ; and\nd. Incorporate lessons learned from internal or external security incidents or breaches into literacy training and awareness techniques.","supplemental_guidance":"Organizations provide basic and advanced levels of literacy training to system users, including measures to test the knowledge level of users. Organizations determine the content of literacy training and awareness based on specific organizational requirements, the systems to which personnel have authorized access, and work environments (e.g., telework). The content includes an understanding of the need for security and privacy as well as actions by users to maintain security and personal privacy and to respond to suspected incidents. The content addresses the need for operations security and the handling of personally identifiable information.\n\nAwareness techniques include displaying posters, offering supplies inscribed with security and privacy reminders, displaying logon screen messages, generating email advisories or notices from organizational officials, and conducting awareness events. Literacy training after the initial training described in [AT-2a.1](#at-2_smt.a.1) is conducted at a minimum frequency consistent with applicable laws, directives, regulations, and policies. Subsequent literacy training may be satisfied by one or more short ad hoc sessions and include topical information on recent attack schemes, changes to organizational security and privacy policies, revised security and privacy expectations, or a subset of topics from the initial training. Updating literacy training and awareness content on a regular basis helps to ensure that the content remains relevant. Events that may precipitate an update to literacy training and awareness content include, but are not limited to, assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines.","implementation_level":"organization","parameters":[{"id":"at-2_prm_1","label":"organization-defined frequency"},{"id":"at-2_prm_2","label":"organization-defined events"},{"id":"at-02_odp.01","label":"frequency"},{"id":"at-02_odp.02","label":"frequency"},{"id":"at-02_odp.03","label":"events"},{"id":"at-02_odp.04","label":"events"},{"id":"at-02_odp.05","label":"awareness techniques"},{"id":"at-02_odp.06","label":"frequency"},{"id":"at-02_odp.07","label":"events"}],"objectives":[{"id":"at-2_obj.a.1-1","label":"AT-02a.01[01]","text":"security literacy training is provided to system users (including managers, senior executives, and contractors) as part of initial training for new users;"},{"id":"at-2_obj.a.1-2","label":"AT-02a.01[02]","text":"privacy literacy training is provided to system users (including managers, senior executives, and contractors) as part of initial training for new users;"},{"id":"at-2_obj.a.1-3","label":"AT-02a.01[03]","text":"security literacy training is provided to system users (including managers, senior executives, and contractors) {{ insert: param, at-02_odp.01 }} thereafter;"},{"id":"at-2_obj.a.1-4","label":"AT-02a.01[04]","text":"privacy literacy training is provided to system users (including managers, senior executives, and contractors) {{ insert: param, at-02_odp.02 }} thereafter;"},{"id":"at-2_obj.a.2-1","label":"AT-02a.02[01]","text":"security literacy training is provided to system users (including managers, senior executives, and contractors) when required by system changes or following {{ insert: param, at-02_odp.03 }};"},{"id":"at-2_obj.a.2-2","label":"AT-02a.02[02]","text":"privacy literacy training is provided to system users (including managers, senior executives, and contractors) when required by system changes or following {{ insert: param, at-02_odp.04 }};"},{"id":"at-2_obj.b","label":"AT-02b.","text":"{{ insert: param, at-02_odp.05 }} are employed to increase the security and privacy awareness of system users;"},{"id":"at-2_obj.c-1","label":"AT-02c.[01]","text":"literacy training and awareness content is updated {{ insert: param, at-02_odp.06 }};"},{"id":"at-2_obj.c-2","label":"AT-02c.[02]","text":"literacy training and awareness content is updated following {{ insert: param, at-02_odp.07 }};"},{"id":"at-2_obj.d","label":"AT-02d.","text":"lessons learned from internal or external security incidents or breaches are incorporated into literacy training and awareness techniques."}],"methods":[{"method":"examine","label":"AT-02-Examine"},{"method":"interview","label":"AT-02-Interview"},{"method":"test","label":"AT-02-Test"}],"references":[{"title":"OMB A-130"},{"title":"SP 800-50"},{"title":"SP 800-160-2"},{"title":"SP 800-181"},{"title":"ODNI CTF"}],"related_controls":["AC-3","AC-17","AC-22","AT-3","AT-4","CP-3","IA-4","IR-2","IR-7","IR-9","PL-4","PM-13","PM-21","PS-7","PT-2","SA-8","SA-16"],"enhancements":[{"id":"AT-2(1)","oscal_id":"at-2.1","family":"AT","title":"Practical Exercises","statement":"Provide practical exercises in literacy training that simulate events and incidents.","supplemental_guidance":"Practical exercises include no-notice social engineering attempts to collect information, gain unauthorized access, or simulate the adverse impact of opening malicious email attachments or invoking, via spear phishing attacks, malicious web links.","implementation_level":"organization","methods":[{"method":"examine","label":"AT-02(01)-Examine"},{"method":"interview","label":"AT-02(01)-Interview"},{"method":"test","label":"AT-02(01)-Test"}],"related_controls":["CA-2","CA-7","CP-4","IR-3"],"is_enhancement":true,"parent_id":"AT-2"},{"id":"AT-2(2)","oscal_id":"at-2.2","family":"AT","title":"Insider Threat","statement":"Provide literacy training on recognizing and reporting potential indicators of insider threat.","supplemental_guidance":"Potential indicators and possible precursors of insider threat can include behaviors such as inordinate, long-term job dissatisfaction; attempts to gain access to information not required for job performance; unexplained access to financial resources; bullying or harassment of fellow employees; workplace violence; and other serious violations of policies, procedures, directives, regulations, rules, or practices. Literacy training includes how to communicate the concerns of employees and management regarding potential indicators of insider threat through channels established by the organization and in accordance with established policies and procedures. Organizations may consider tailoring insider threat awareness topics to the role. For example, training for managers may be focused on changes in the behavior of team members, while training for employees may be focused on more general observations.","implementation_level":"organization","objectives":[{"id":"at-2.2_obj-1","label":"AT-02(02)[01]","text":"literacy training on recognizing potential indicators of insider threat is provided;"},{"id":"at-2.2_obj-2","label":"AT-02(02)[02]","text":"literacy training on reporting potential indicators of insider threat is provided."}],"methods":[{"method":"examine","label":"AT-02(02)-Examine"},{"method":"interview","label":"AT-02(02)-Interview"}],"related_controls":["PM-12"],"is_enhancement":true,"parent_id":"AT-2"},{"id":"AT-2(3)","oscal_id":"at-2.3","family":"AT","title":"Social Engineering and Mining","statement":"Provide literacy training on recognizing and reporting potential and actual instances of social engineering and social mining.","supplemental_guidance":"Social engineering is an attempt to trick an individual into revealing information or taking an action that can be used to breach, compromise, or otherwise adversely impact a system. Social engineering includes phishing, pretexting, impersonation, baiting, quid pro quo, thread-jacking, social media exploitation, and tailgating. Social mining is an attempt to gather information about the organization that may be used to support future attacks. Literacy training includes information on how to communicate the concerns of employees and management regarding potential and actual instances of social engineering and data mining through organizational channels based on established policies and procedures.","implementation_level":"organization","objectives":[{"id":"at-2.3_obj-1","label":"AT-02(03)[01]","text":"literacy training on recognizing potential and actual instances of social engineering is provided;"},{"id":"at-2.3_obj-2","label":"AT-02(03)[02]","text":"literacy training on reporting potential and actual instances of social engineering is provided;"},{"id":"at-2.3_obj-3","label":"AT-02(03)[03]","text":"literacy training on recognizing potential and actual instances of social mining is provided;"},{"id":"at-2.3_obj-4","label":"AT-02(03)[04]","text":"literacy training on reporting potential and actual instances of social mining is provided."}],"methods":[{"method":"examine","label":"AT-02(03)-Examine"},{"method":"interview","label":"AT-02(03)-Interview"}],"is_enhancement":true,"parent_id":"AT-2"},{"id":"AT-2(4)","oscal_id":"at-2.4","family":"AT","title":"Suspicious Communications and Anomalous System Behavior","statement":"Provide literacy training on recognizing suspicious communications and anomalous behavior in organizational systems using <indicators of malicious code>.","supplemental_guidance":"A well-trained workforce provides another organizational control that can be employed as part of a defense-in-depth strategy to protect against malicious code coming into organizations via email or the web applications. Personnel are trained to look for indications of potentially suspicious email (e.g., receiving an unexpected email, receiving an email containing strange or poor grammar, or receiving an email from an unfamiliar sender that appears to be from a known sponsor or contractor). Personnel are also trained on how to respond to suspicious email or web communications. For this process to work effectively, personnel are trained and made aware of what constitutes suspicious communications. Training personnel on how to recognize anomalous behaviors in systems can provide organizations with early warning for the presence of malicious code. Recognition of anomalous behavior by organizational personnel can supplement malicious code detection and protection tools and systems employed by organizations.","implementation_level":"organization","parameters":[{"id":"at-02.04_odp","label":"indicators of malicious code"}],"methods":[{"method":"examine","label":"AT-02(04)-Examine"},{"method":"interview","label":"AT-02(04)-Interview"}],"is_enhancement":true,"parent_id":"AT-2"},{"id":"AT-2(5)","oscal_id":"at-2.5","family":"AT","title":"Advanced Persistent Threat","statement":"Provide literacy training on the advanced persistent threat.","supplemental_guidance":"An effective way to detect advanced persistent threats (APT) and to preclude successful attacks is to provide specific literacy training for individuals. Threat literacy training includes educating individuals on the various ways that APTs can infiltrate the organization (e.g., through websites, emails, advertisement pop-ups, articles, and social engineering). Effective training includes techniques for recognizing suspicious emails, use of removable systems in non-secure settings, and the potential targeting of individuals at home.","implementation_level":"organization","methods":[{"method":"examine","label":"AT-02(05)-Examine"},{"method":"interview","label":"AT-02(05)-Interview"}],"is_enhancement":true,"parent_id":"AT-2"},{"id":"AT-2(6)","oscal_id":"at-2.6","family":"AT","title":"Cyber Threat Environment","statement":"(a) Provide literacy training on the cyber threat environment; and\n(b) Reflect current cyber threat information in system operations.","supplemental_guidance":"Since threats continue to change over time, threat literacy training by the organization is dynamic. Moreover, threat literacy training is not performed in isolation from the system operations that support organizational mission and business functions.","implementation_level":"organization","objectives":[{"id":"at-2.6_obj.a","label":"AT-02(06)(a)","text":"literacy training on the cyber threat environment is provided;"},{"id":"at-2.6_obj.b","label":"AT-02(06)(b)","text":"system operations reflects current cyber threat information."}],"methods":[{"method":"examine","label":"AT-02(06)-Examine"},{"method":"interview","label":"AT-02(06)-Interview"}],"related_controls":["RA-3"],"is_enhancement":true,"parent_id":"AT-2"}]},{"id":"AT-3","oscal_id":"at-3","family":"AT","title":"Role-based Training","statement":"a. Provide role-based security and privacy training to personnel with the following roles and responsibilities: <organization-defined roles and responsibilities>:\n  Provide role-based security and privacy training to personnel with the following roles and responsibilities: <organization-defined roles and responsibilities>:\n  1. Before authorizing access to the system, information, or performing assigned duties, and <frequency> thereafter; and\n  2. When required by system changes;\nb. Update role-based training content <frequency> and following <events> ; and\nc. Incorporate lessons learned from internal or external security incidents or breaches into role-based training.","supplemental_guidance":"Organizations determine the content of training based on the assigned roles and responsibilities of individuals as well as the security and privacy requirements of organizations and the systems to which personnel have authorized access, including technical training specifically tailored for assigned duties. Roles that may require role-based training include senior leaders or management officials (e.g., head of agency/chief executive officer, chief information officer, senior accountable official for risk management, senior agency information security officer, senior agency official for privacy), system owners; authorizing officials; system security officers; privacy officers; acquisition and procurement officials; enterprise architects; systems engineers; software developers; systems security engineers; privacy engineers; system, network, and database administrators; auditors; personnel conducting configuration management activities; personnel performing verification and validation activities; personnel with access to system-level software; control assessors; personnel with contingency planning and incident response duties; personnel with privacy management responsibilities; and personnel with access to personally identifiable information.\n\nComprehensive role-based training addresses management, operational, and technical roles and responsibilities covering physical, personnel, and technical controls. Role-based training also includes policies, procedures, tools, methods, and artifacts for the security and privacy roles defined. Organizations provide the training necessary for individuals to fulfill their responsibilities related to operations and supply chain risk management within the context of organizational security and privacy programs. Role-based training also applies to contractors who provide services to federal agencies. Types of training include web-based and computer-based training, classroom-style training, and hands-on training (including micro-training). Updating role-based training on a regular basis helps to ensure that the content remains relevant and effective. Events that may precipitate an update to role-based training content include, but are not limited to, assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines.","implementation_level":"organization","parameters":[{"id":"at-3_prm_1","label":"organization-defined roles and responsibilities"},{"id":"at-03_odp.01","label":"roles and responsibilities"},{"id":"at-03_odp.02","label":"roles and responsibilities"},{"id":"at-03_odp.03","label":"frequency"},{"id":"at-03_odp.04","label":"frequency"},{"id":"at-03_odp.05","label":"events"}],"objectives":[{"id":"at-3_obj.a.1-1","label":"AT-03a.01[01]","text":"role-based security training is provided to {{ insert: param, at-03_odp.01 }} before authorizing access to the system, information, or performing assigned duties;"},{"id":"at-3_obj.a.1-2","label":"AT-03a.01[02]","text":"role-based privacy training is provided to {{ insert: param, at-03_odp.02 }} before authorizing access to the system, information, or performing assigned duties;"},{"id":"at-3_obj.a.1-3","label":"AT-03a.01[03]","text":"role-based security training is provided to {{ insert: param, at-03_odp.01 }} {{ insert: param, at-03_odp.03 }} thereafter;"},{"id":"at-3_obj.a.1-4","label":"AT-03a.01[04]","text":"role-based privacy training is provided to {{ insert: param, at-03_odp.02 }} {{ insert: param, at-03_odp.03 }} thereafter;"},{"id":"at-3_obj.a.2-1","label":"AT-03a.02[01]","text":"role-based security training is provided to personnel with assigned security roles and responsibilities when required by system changes;"},{"id":"at-3_obj.a.2-2","label":"AT-03a.02[02]","text":"role-based privacy training is provided to personnel with assigned security roles and responsibilities when required by system changes;"},{"id":"at-3_obj.b-1","label":"AT-03b.[01]","text":"role-based training content is updated {{ insert: param, at-03_odp.04 }};"},{"id":"at-3_obj.b-2","label":"AT-03b.[02]","text":"role-based training content is updated following {{ insert: param, at-03_odp.05 }};"},{"id":"at-3_obj.c","label":"AT-03c.","text":"lessons learned from internal or external security incidents or breaches are incorporated into role-based training."}],"methods":[{"method":"examine","label":"AT-03-Examine"},{"method":"interview","label":"AT-03-Interview"},{"method":"test","label":"AT-03-Test"}],"references":[{"title":"OMB A-130"},{"title":"SP 800-50"},{"title":"SP 800-181"}],"related_controls":["AC-3","AC-17","AC-22","AT-2","AT-4","CP-3","IR-2","IR-4","IR-7","IR-9","PL-4","PM-13","PM-23","PS-7","PS-9","SA-3","SA-8","SA-11","SA-16","SR-5","SR-6","SR-11"],"enhancements":[{"id":"AT-3(1)","oscal_id":"at-3.1","family":"AT","title":"Environmental Controls","statement":"Provide <personnel or roles> with initial and <frequency> training in the employment and operation of environmental controls.","supplemental_guidance":"Environmental controls include fire suppression and detection devices or systems, sprinkler systems, handheld fire extinguishers, fixed fire hoses, smoke detectors, temperature or humidity, heating, ventilation, air conditioning, and power within the facility.","implementation_level":"organization","parameters":[{"id":"at-03.01_odp.01","label":"personnel or roles"},{"id":"at-03.01_odp.02","label":"frequency"}],"methods":[{"method":"examine","label":"AT-03(01)-Examine"},{"method":"interview","label":"AT-03(01)-Interview"}],"related_controls":["PE-1","PE-11","PE-13","PE-14","PE-15"],"is_enhancement":true,"parent_id":"AT-3"},{"id":"AT-3(2)","oscal_id":"at-3.2","family":"AT","title":"Physical Security Controls","statement":"Provide <personnel or roles> with initial and <frequency> training in the employment and operation of physical security controls.","supplemental_guidance":"Physical security controls include physical access control devices, physical intrusion and detection alarms, operating procedures for facility security guards, and monitoring or surveillance equipment.","implementation_level":"organization","parameters":[{"id":"at-03.02_odp.01","label":"personnel or roles"},{"id":"at-03.02_odp.02","label":"frequency"}],"methods":[{"method":"examine","label":"AT-03(02)-Examine"},{"method":"interview","label":"AT-03(02)-Interview"}],"related_controls":["PE-2","PE-3","PE-4"],"is_enhancement":true,"parent_id":"AT-3"},{"id":"AT-3(3)","oscal_id":"at-3.3","family":"AT","title":"Practical Exercises","statement":"Provide practical exercises in security and privacy training that reinforce training objectives.","supplemental_guidance":"Practical exercises for security include training for software developers that addresses simulated attacks that exploit common software vulnerabilities or spear or whale phishing attacks targeted at senior leaders or executives. Practical exercises for privacy include modules with quizzes on identifying and processing personally identifiable information in various scenarios or scenarios on conducting privacy impact assessments.","implementation_level":"organization","objectives":[{"id":"at-3.3_obj-1","label":"AT-03(03)[01]","text":"practical exercises in security training that reinforce training objectives are provided;"},{"id":"at-3.3_obj-2","label":"AT-03(03)[02]","text":"practical exercises in privacy training that reinforce training objectives are provided."}],"methods":[{"method":"examine","label":"AT-03(03)-Examine"},{"method":"interview","label":"AT-03(03)-Interview"}],"is_enhancement":true,"parent_id":"AT-3"},{"id":"AT-3(4)","oscal_id":"at-3.4","family":"AT","title":"Suspicious Communications and Anomalous System Behavior","statement":"","is_enhancement":true,"parent_id":"AT-3"},{"id":"AT-3(5)","oscal_id":"at-3.5","family":"AT","title":"Processing Personally Identifiable Information","statement":"Provide <personnel or roles> with initial and <frequency> training in the employment and operation of personally identifiable information processing and transparency controls.","supplemental_guidance":"Personally identifiable information processing and transparency controls include the organization’s authority to process personally identifiable information and personally identifiable information processing purposes. Role-based training for federal agencies addresses the types of information that may constitute personally identifiable information and the risks, considerations, and obligations associated with its processing. Such training also considers the authority to process personally identifiable information documented in privacy policies and notices, system of records notices, computer matching agreements and notices, privacy impact assessments, [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) statements, contracts, information sharing agreements, memoranda of understanding, and/or other documentation.","implementation_level":"organization","parameters":[{"id":"at-03.05_odp.01","label":"personnel or roles"},{"id":"at-03.05_odp.02","label":"frequency"}],"methods":[{"method":"examine","label":"AT-03(05)-Examine"},{"method":"interview","label":"AT-03(05)-Interview"}],"related_controls":["PT-2","PT-3","PT-5","PT-6"],"is_enhancement":true,"parent_id":"AT-3"}]},{"id":"AT-4","oscal_id":"at-4","family":"AT","title":"Training Records","statement":"a. Document and monitor information security and privacy training activities, including security and privacy awareness training and specific role-based security and privacy training; and\nb. Retain individual training records for <time period>.","supplemental_guidance":"Documentation for specialized training may be maintained by individual supervisors at the discretion of the organization. The National Archives and Records Administration provides guidance on records retention for federal agencies.","implementation_level":"organization","parameters":[{"id":"at-04_odp","label":"time period"}],"objectives":[{"id":"at-4_obj.a-1","label":"AT-04a.[01]","text":"information security and privacy training activities, including security and privacy awareness training and specific role-based security and privacy training, are documented;"},{"id":"at-4_obj.a-2","label":"AT-04a.[02]","text":"information security and privacy training activities, including security and privacy awareness training and specific role-based security and privacy training, are monitored;"},{"id":"at-4_obj.b","label":"AT-04b.","text":"individual training records are retained for {{ insert: param, at-04_odp }}."}],"methods":[{"method":"examine","label":"AT-04-Examine"},{"method":"interview","label":"AT-04-Interview"},{"method":"test","label":"AT-04-Test"}],"references":[{"title":"OMB A-130"}],"related_controls":["AT-2","AT-3","CP-3","IR-2","PM-14","SI-12"]},{"id":"AT-5","oscal_id":"at-5","family":"AT","title":"Contacts with Security Groups and Associations","statement":""},{"id":"AT-6","oscal_id":"at-6","family":"AT","title":"Training Feedback","statement":"Provide feedback on organizational training results to the following personnel <frequency>: <personnel>.","supplemental_guidance":"Training feedback includes awareness training results and role-based training results. Training results, especially failures of personnel in critical roles, can be indicative of a potentially serious problem. Therefore, it is important that senior managers are made aware of such situations so that they can take appropriate response actions. Training feedback supports the evaluation and update of organizational training described in [AT-2b](#at-2_smt.b) and [AT-3b](#at-3_smt.b).","implementation_level":"organization","parameters":[{"id":"at-06_odp.01","label":"frequency"},{"id":"at-06_odp.02","label":"personnel"}],"methods":[{"method":"examine","label":"AT-06-Examine"},{"method":"interview","label":"AT-06-Interview"},{"method":"test","label":"AT-06-Test"}]}]};
